/* Déclic — Anglais B1 (unités 1 à 3). Format : docs/ANGLAIS.md */
(()=>{
// Variantes de réponse : X('I {have|’ve} {lived|been living} here') développe toutes les combinaisons.
// La correction ignore déjà casse, ponctuation et contractions (sauf ’s et ’d) : seules les vraies variantes comptent.
const X=(...ss)=>{ const out=[]; ss.forEach(s=>{ let a=['']; s.split(/(\{[^}]*\})/).forEach(part=>{
  if(part.startsWith('{')&&part.endsWith('}')){ const o=part.slice(1,-1).split('|'); a=a.flatMap(x=>o.map(y=>x+y)); } else a=a.map(x=>x+part); });
  a.forEach(x=>{ x=x.replace(/\s+/g,' ').replace(/\s+([,.!?:;])/g,'$1').trim(); if(!out.includes(x)) out.push(x); }); }); return out; };

COURS.push(
{subj:'en', sem:'b1', id:'en-b1-identity', o:1, h:'Who I am', p:'Parler de soi en détail : parcours, personnalité, habitudes et situation du moment, avec le présent simple, le présent continu et les verbes d’état.', steps:[
 {kind:'Écoute', h:'Looking for a flatmate',
  p:`<p>By the end of this unit, you will be able to talk about yourself in detail: where you come from, what you are like, your habits and what is happening in your life at the moment.</p>
<p>Maya has a room to rent in her flat in London. Julien, from Switzerland, has come to see it. <b>Listen without reading</b>, twice if you like, then answer. The text appears after your answer.</p>
<p><b>Question:</b> why is Julien living in London at the moment?</p>`,
  audio:[['Maya','So, Julien, tell me a bit about yourself. What do you do?'],['Julien','Well, I’m an architect. I’m originally from Lausanne, in Switzerland, but at the moment I’m working for a firm here in London. It’s a six-month contract, so I’m looking for a room until March.'],['Maya','Nice. And what are you like to live with? Be honest!'],['Julien','I think I’m fairly easy-going. I’m quite tidy, and I tend to keep to myself during the week, because I work long hours. But I’m not shy, I promise. I love cooking, so I often make dinner for friends at the weekend.'],['Maya','That sounds perfect. Ben, our other flatmate, is really sociable, but he’s a bit messy. He’s always leaving his bike in the hall!'],['Julien','That’s fine. Actually, I’m cycling to work too these days, so I understand.'],['Maya','Great. Do you have any questions for me?'],['Julien','Yes. How much is the rent, and does that include bills?'],['Maya','It’s eight hundred pounds a month, bills included.']], cache:true,
  opts:['He is studying architecture at a London university.','He has a six-month contract with an architecture firm.','He has moved to London for good with his family.','He is visiting his friend Ben for a few weeks.'], ans:1,
  why:'Julien dit <i lang="en">at the moment I’m working for a firm here in London. It’s a six-month contract</i>. Remarque le présent continu : c’est une situation <b>temporaire</b>. Pour son métier, stable, il dit <i lang="en">I’m an architect</i>.'},

 {kind:'Vocabulaire', h:'Describing personality',
  p:`<p>Here are useful adjectives and expressions to describe what people are like. Tap a line to hear it and repeat it aloud. These words go into your <b>vocabulary review</b>, which will ask you for them again tomorrow, then in a few days.</p>`,
  mots:[['easy-going / easygoing','facile à vivre, décontracté','I’m fairly easy-going: not much makes me angry.'],['outgoing / sociable','extraverti, sociable','Ben is really outgoing and loves parties.'],['shy','timide','He’s a bit shy with people he doesn’t know.'],['reliable','fiable, sur qui on peut compter','If Sam says he’ll come, he comes. He’s very reliable.'],['hard-working','travailleur','My boss is hard-working but fair.'],['self-confident','sûr de soi','She seems self-confident, but she gets nervous before exams.'],['open-minded','ouvert d’esprit','My grandparents are surprisingly open-minded.'],['stubborn','têtu','He’s so stubborn: he never admits he’s wrong.'],['moody','lunatique, d’humeur changeante','Teenagers can be quite moody.'],['tidy / messy','ordonné / désordonné','Julien is tidy, but Ben is a bit messy.'],['sensitive','sensible (émotif)','Don’t laugh at him: he’s very sensitive.'],['sensible','raisonnable, sensé','Saving some money was a sensible decision.'],['nice / friendly','sympathique','Your new neighbours seem really nice.'],['to get on well with (someone)','bien s’entendre avec quelqu’un','I get on well with my colleagues.']],
  note:'<b>Faux amis :</b> <i lang="en">sensible</i> = raisonnable, et « sensible » se dit <i lang="en">sensitive</i>. <i lang="en">Sympathetic</i> = compatissant ; « sympathique » se dit <i lang="en">nice</i> ou <i lang="en">friendly</i>. Le mot « sympathic » n’existe pas. En américain, on dit aussi <i lang="en">get along with</i> pour <i lang="en">get on with</i>.'},

 {kind:'Pratique', h:'Your turn: describe someone',
  p:`<p>Translate into English, using adjectives from the list.</p><p><b>Question:</b> « Mon frère est très têtu, mais il est fiable. »</p>`, lab:'Your sentence',
  txt:X('My brother is {very|really|so} stubborn, {but|although|though} he is {|also }{reliable|dependable|trustworthy}.','My brother is {very|really|so} stubborn, {but|although|though} he’s {|also }{reliable|dependable|trustworthy}.','My brother’s {very|really|so} stubborn, {but|although|though} he is {|also }{reliable|dependable|trustworthy}.','My brother’s {very|really|so} stubborn, {but|although|though} he’s {|also }{reliable|dependable|trustworthy}.','My brother is {very|really|so} stubborn but {reliable|dependable|trustworthy}.'),
  why:'<i lang="en">stubborn</i> = têtu, <i lang="en">reliable</i> = fiable. Pas de calque comme « He is someone of reliable » : l’adjectif suffit après <i lang="en">is</i>.'},

 {kind:'Vocabulaire', h:'Talking about yourself',
  p:`<p>These ready-made phrases help you talk about yourself for a long time without stopping. Learn them as whole blocks. Tap a line to hear it.</p>`,
  mots:[['I’m originally from…','Je suis originaire de…','I’m originally from Lausanne, but I live in London now.'],['I grew up in…','J’ai grandi à…','I grew up in a small village near Fribourg.'],['at the moment / currently','en ce moment, actuellement','At the moment I’m working on a big project.'],['these days','ces temps-ci','I’m cycling to work these days.'],['I work as a…','Je travaille comme…','I work as a nurse in a children’s hospital.'],['I’m in my final year','Je suis en dernière année','I’m in my final year at university.'],['to be into (something)','être passionné par, adorer','I’m really into climbing at the moment.'],['to be keen on (something)','aimer, être emballé par','I’m not very keen on big parties.'],['I tend to…','J’ai tendance à…','I tend to keep to myself during the week.'],['in my spare time','pendant mon temps libre','In my spare time I play the guitar.'],['I’m a bit of a… (night owl)','Je suis un peu… (un oiseau de nuit)','I’m a bit of a night owl: I work best after ten.'],['to be honest','à vrai dire, franchement','To be honest, I’m not a morning person.'],['What I like most about… is…','Ce que je préfère dans… c’est…','What I like most about my job is the people.']],
  note:'<b>Attention :</b> <i lang="en">actually</i> veut dire « en fait », pas « actuellement ». « Actuellement » se dit <i lang="en">currently</i> ou <i lang="en">at the moment</i>. Julien dit <i lang="en">Actually, I’m cycling to work too</i> : « en fait, moi aussi… ».'},

 {kind:'Pratique', h:'Your turn: where you’re from',
  p:`<p>Translate into English.</p><p><b>Question:</b> « Je suis originaire de Lyon, mais je vis à Genève. »</p>`, lab:'Your sentence',
  txt:X('I am originally from Lyon, but I {live|am living} in Geneva{| now| at the moment}.','I {originally come|come originally} from Lyon, but I {live|am living} in Geneva{| now| at the moment}.','Originally I am from Lyon, but I {live|am living} in Geneva{| now| at the moment}.','I am from Lyon originally, but I {live|am living} in Geneva{| now| at the moment}.','I come from Lyon, but I {live|am living} in Geneva{| now| at the moment}.','I am from Lyon, but I {live|am living} in Geneva{| now| at the moment}.'),
  why:'<i lang="en">I’m originally from Lyon</i> est la façon la plus naturelle de dire « je suis originaire de ». <i lang="en">I live in Geneva</i> si c’est ton domicile stable, <i lang="en">I’m living in Geneva</i> si c’est temporaire.'},

 {kind:'Grammaire', h:'Present simple or present continuous?',
  p:`<p>Dans le dialogue, Julien dit <i lang="en">I’m an architect</i> et <i lang="en">I often make dinner for friends</i>, mais aussi <i lang="en">at the moment I’m working for a firm here in London</i>. Pourquoi deux présents&nbsp;? Parce que l’anglais distingue ce qui est <b>stable</b> de ce qui est <b>en cours ou temporaire</b>.</p>
<div class="def"><p><b>Présent simple</b> (<i lang="en">I work, she works, do you work?, he doesn’t work</i>) : les faits permanents, les habitudes et leur fréquence, les goûts, les vérités générales. <i lang="en">I live in Lausanne. I often cook at the weekend. Water boils at 100 °C.</i></p>
<p><b>Présent continu</b> (<i lang="en">am/is/are + -ing</i>) : ce qui se passe au moment où l’on parle ; une <b>situation temporaire</b> (<i lang="en">this month, these days, at the moment</i>) ; un <b>changement en cours</b> (<i lang="en">My English is getting better</i>) ; et, avec <i lang="en">always</i>, une habitude <b>agaçante</b> (<i lang="en">He’s always leaving his bike in the hall!</i>).</p></div>
<div class="idea"><p>Le présent simple, c’est la photo de ta vie : qui tu es, ce que tu fais d’habitude. Le présent continu, c’est le film de la période actuelle : ce qui bouge, ce qui va se terminer. Compare <i lang="en">I live in Lausanne</i> (c’est chez moi) et <i lang="en">I’m living in London until March</i> (pour quelques mois).</p></div>
<div class="ex"><p><i lang="en">What do you do?</i> = Quel est ton métier&nbsp;? – <i lang="en">I’m a nurse.</i><br><i lang="en">What are you doing?</i> = Que fais-tu (en ce moment)&nbsp;? – <i lang="en">I’m looking for my keys.</i><br><i lang="en">Prices are going up.</i> = Les prix augmentent (tendance actuelle).</p></div>
<div class="warn"><p>Le français n’a qu’un présent : « je travaille » se traduit par <i lang="en">I work</i> ou par <i lang="en">I’m working</i>. Demande-toi toujours : permanent ou temporaire, habitude ou en cours&nbsp;? Et attention au faux ami : « actuellement » = <i lang="en">currently</i>, <i lang="en">at the moment</i> ; <i lang="en">actually</i> = « en fait ».</p></div>`,
  audio:'I live in Lausanne, but I’m living in London until March. What do you do? I’m a nurse. What are you doing? I’m looking for my keys.'},

 {kind:'Méthode', h:'Choosing the right present',
  p:`<p><b>Quand :</b> chaque fois que tu parles de toi ou des autres au présent. <b>Pourquoi ça marche :</b> le choix ne dépend pas du verbe français, mais de ce que tu veux dire : stable ou temporaire, habitude ou action en cours. <b>Comment :</b> pose-toi trois questions, dans cet ordre.</p>
<ul><li><b>1. Le verbe décrit-il un état</b> (savoir, aimer, vouloir, posséder, sembler…)&nbsp;? Alors présent simple, même « en ce moment » : <i lang="en">I know, I want, it seems</i>.</li><li><b>2. Y a-t-il un marqueur de temps&nbsp;?</b> <i lang="en">usually, often, every day, never</i> → présent simple. <i lang="en">now, at the moment, this week, these days, currently</i> → présent continu.</li><li><b>3. Sinon, quel sens&nbsp;?</b> Permanent, habitude, vérité générale → simple. En cours, temporaire, en train de changer → continu.</li></ul>
<p>Puis forme le verbe : <b>-s</b> à la 3e personne du simple (<i lang="en">she teaches</i>), <b>do/does</b> pour ses questions et négations ; <b>am/is/are + -ing</b> pour le continu.</p>`,
  demo:{enonce:'Complète : <i lang="en">Normally Clara ___ (teach) maths in Geneva, but this year she ___ (teach) in Montreal, and she ___ (love) it.</i>',
   etapes:[{f:'<i lang="en">Normally Clara <b>teaches</b> maths in Geneva</i>',w:'<i lang="en">Normally</i> annonce la situation habituelle → présent simple. 3e personne : <i lang="en">teach</i> → <i lang="en">teaches</i> (<i lang="en">-es</i> après <i lang="en">ch</i>).'},
    {f:'<i lang="en">but this year she <b>is teaching</b> in Montreal</i>',w:'<i lang="en">this year</i> + une situation temporaire → présent continu.'},
    {f:'<i lang="en">and she <b>loves</b> it</i>',w:'<i lang="en">love</i> est un verbe d’état (un sentiment) → présent simple, même si l’on parle de cette année.'}],
   conclusion:'<i lang="en">Normally Clara teaches maths in Geneva, but this year she’s teaching in Montreal, and she loves it.</i>'}},

 {kind:'Pratique', h:'Right now or usually?',
  p:`<p>Complete the sentence with the correct form of the verb in brackets. Write only the missing words.</p><p><b>Question:</b> <i lang="en">Sorry, I can’t talk now. I ___ (cook) dinner.</i></p>`, lab:'Missing words', txt:['am cooking'],
  why:'L’action est en cours au moment où l’on parle (<i lang="en">now</i>) → présent continu : <i lang="en">I’m cooking dinner</i>.'},

 {kind:'Pratique', h:'A change in progress',
  p:`<p>Complete the sentence with the correct form of the verb in brackets. Write only the missing words.</p><p><b>Question:</b> <i lang="en">My English ___ (get) better because I watch a lot of series in English.</i></p>`, lab:'Missing words', txt:X('is getting','’s getting'),
  why:'Un changement en cours → présent continu : <i lang="en">is getting better</i>. En revanche, <i lang="en">I watch a lot of series</i> est une habitude → présent simple.'},

 {kind:'Grammaire', h:'State verbs',
  p:`<p>Julien dirait <i lang="en">I understand</i>, jamais « I’m understanding », même pour parler de maintenant. Pourquoi&nbsp;? Certains verbes ne décrivent pas une action mais un <b>état</b> : ils refusent en général la forme en <i lang="en">-ing</i>.</p>
<div class="def"><p><b>Verbes d’état</b> courants :</p><ul><li>pensée : <i lang="en">know, understand, believe, remember, mean, realise, agree</i> ;</li><li>sentiments et désirs : <i lang="en">like, love, hate, prefer, want, need</i> ;</li><li>possession : <i lang="en">have</i> (posséder), <i lang="en">own, belong to</i> ;</li><li>apparence et sens : <i lang="en">seem, look like, sound, smell, taste</i>.</li></ul></div>
<div class="idea"><p>Un état n’a ni début ni fin visibles : on ne peut pas être « en train de savoir ». Mais certains verbes ont <b>deux sens</b>, l’un d’état, l’autre d’action : <i lang="en">I think he’s nice</i> (opinion) / <i lang="en">I’m thinking about it</i> (je réfléchis) ; <i lang="en">I have a car</i> (possession) / <i lang="en">I’m having lunch, a shower, a great time</i> (action) ; <i lang="en">I see</i> (je comprends) / <i lang="en">I’m seeing Tom tonight</i> (je vois Tom ce soir) ; <i lang="en">He is stubborn</i> (de caractère) / <i lang="en">He’s being stubborn</i> (il fait sa tête de mule, en ce moment).</p></div>
<div class="ex"><p><i lang="en">I don’t understand this word.</i> (pas <i lang="en">I’m not understanding</i>)<br><i lang="en">This bike belongs to Ben.</i><br><i lang="en">We’re having dinner. Can I call you back?</i></p></div>
<div class="warn"><p>Deux pièges classiques : <i lang="en">agree</i> est un verbe, donc <b>I agree</b>, jamais « I am agree ». Et le slogan <i lang="en">I’m loving it</i> est un jeu publicitaire : dans un anglais soigné, on dit <i lang="en">I love it</i>.</p></div>`,
  audio:'I think he’s nice. I’m thinking about it. I have a car. I’m having lunch. He is stubborn. He’s being stubborn today.'},

 {kind:'Pratique', h:'Correct the mistake',
  p:`<p>This sentence contains a mistake. Write the correct sentence.</p><p><b>Question:</b> <i lang="en">I’m not understanding what you mean.</i></p>`, lab:'Correct sentence', txt:X('I do not understand what you mean.'),
  why:'<i lang="en">understand</i> est un verbe d’état : présent simple, même pour maintenant. <i lang="en">I don’t understand what you mean.</i>'},

 {kind:'Pratique', h:'Think or thinking?',
  p:`<p>Translate into English. Be careful: here, « réfléchir » is an action in progress.</p><p><b>Question:</b> « Je réfléchis à changer de travail. »</p>`, lab:'Your sentence',
  txt:X('I am thinking {of|about} changing {jobs|my job|job}.','I am considering changing {jobs|my job|job}.'),
  why:'<i lang="en">think</i> au sens de « réfléchir, envisager » est une action : <i lang="en">I’m thinking of changing jobs</i> (ou <i lang="en">about</i>). Au sens d’opinion, il reste au simple : <i lang="en">I think it’s a good idea</i>.'},

 {kind:'Pratique', h:'An annoying habit',
  p:`<p>Put the words in the right order to complain about your flatmate.</p><p><b>Question:</b> what annoying thing does she keep doing?</p>`,
  ordre:['She’s','always','borrowing','my','clothes','without','asking.'],
  why:'<i lang="en">She’s always borrowing my clothes without asking.</i> Présent continu + <i lang="en">always</i> = une habitude qui agace. <i lang="en">always</i> se place entre <i lang="en">is</i> et le verbe en <i lang="en">-ing</i>.'},

 {kind:'Prononciation', h:'Word stress in adjectives',
  p:`<p>En anglais, chaque mot de deux syllabes ou plus a <b>une syllabe forte</b> ; les autres sont faibles, souvent réduites au son /ə/ (le schwa). Les francophones accentuent volontiers la dernière syllabe (« relia<b>ble</b> »). En anglais, c’est re<b>LI</b>able, et le reste s’efface.</p>
<div class="def"><ul><li>Beaucoup d’adjectifs de deux ou trois syllabes : accent sur la 1re. <b>STUB</b>born, <b>MOO</b>dy, <b>HO</b>nest, <b>PA</b>tient, <b>SEN</b>sitive, <b>SEN</b>sible.</li><li>Suffixes <i lang="en">-ious</i> et <i lang="en">-ic</i> : accent sur la syllabe juste avant. am<b>BI</b>tious, <b>CU</b>rious, ener<b>GE</b>tic, opti<b>MIS</b>tic.</li><li>Adjectifs composés : accent sur la 2e partie. easy-<b>GO</b>ing, hard-<b>WOR</b>king, open-<b>MIN</b>ded, self-<b>CON</b>fident.</li></ul></div>
<div class="warn"><p>Dans <i lang="en">reliable</i> /rɪˈlaɪ.ə.bəl/, deux syllabes sur quatre se réduisent à /ə/. Et le <b>h</b> de <i lang="en">honest</i> est muet (comme dans <i lang="en">hour</i>), alors qu’il se prononce dans <i lang="en">hard-working</i> et <i lang="en">happy</i>.</p></div>`,
  audio:'reliable, stubborn, sensitive, honest, ambitious, curious, energetic, optimistic, easy-going, hard-working, open-minded, self-confident.'},

 {kind:'Oral', h:'Repeat: stress and rhythm',
  p:`<p>Listen, then say the sentence. Make the strong syllables clearly stronger: <i lang="en">To be <b>HO</b>nest, I’m quite am<b>BI</b>tious, but I’m also very easy-<b>GO</b>ing.</i></p>`,
  dire:'To be honest, I’m quite ambitious, but I’m also very easy-going.',
  note:'Le micro doit être autorisé la première fois. Si un mot reste en rouge, réécoute-le lentement, puis recommence.'},

 {kind:'Lecture', h:'Meet the team',
  p:`<p>Read this article from a company newsletter, then answer. You can also listen to it.</p>
<div class="blk" data-t="Newsletter: Meet the team"><p lang="en">This month we’re introducing Amira Haddad, who joined our customer service team in September. Amira is originally from Marseille, but she grew up in Manchester, so she switches between French and English without thinking. She usually works on the morning shift, which suits her perfectly. “I’m a bit of a morning person,” she admits. “I get up at half past five and I’m at my most productive before lunch.” Her colleagues describe her as calm, reliable and very patient, even with the most difficult callers. At the moment Amira is studying for a degree in psychology in the evenings, so she’s quite busy, but she still finds time for her real passion: running. She’s currently training for her first half marathon, which takes place in Liverpool next spring. “I’m not naturally sporty,” she says, “but I’m stubborn. When I decide to do something, I do it.” If you need help with a customer complaint, or just a good running playlist, Amira is the person to ask.</p></div>
<p><b>Question:</b> which sentence about Amira is true?</p>`,
  audio:'This month we’re introducing Amira Haddad, who joined our customer service team in September. Amira is originally from Marseille, but she grew up in Manchester, so she switches between French and English without thinking. She usually works on the morning shift, which suits her perfectly. “I’m a bit of a morning person,” she admits. “I get up at half past five and I’m at my most productive before lunch.” Her colleagues describe her as calm, reliable and very patient, even with the most difficult callers. At the moment Amira is studying for a degree in psychology in the evenings, so she’s quite busy, but she still finds time for her real passion: running. She’s currently training for her first half marathon, which takes place in Liverpool next spring. “I’m not naturally sporty,” she says, “but I’m stubborn. When I decide to do something, I do it.” If you need help with a customer complaint, or just a good running playlist, Amira is the person to ask.',
  opts:['She works in the evenings and studies in the mornings.','She is training for her first half marathon.','She has always been naturally good at sport.','She grew up in Marseille.'], ans:1,
  why:'<i lang="en">She’s currently training for her first half marathon</i>. Elle travaille le matin et étudie le soir, elle a grandi à Manchester, et elle dit <i lang="en">I’m not naturally sporty</i>.'},

 {kind:'Pratique', h:'Find the expression',
  p:`<p>Look at the text about Amira again.</p><p><b>Question:</b> which expression does Amira use to say « je suis plutôt du matin »? Write it.</p>`, lab:'The expression',
  txt:X('I am a bit of a morning person','a bit of a morning person','I am a morning person','a morning person'),
  why:'<i lang="en">I’m a bit of a morning person</i>. <i lang="en">a bit of a…</i> adoucit : « je suis un peu… ». Le contraire : <i lang="en">a night owl</i>, un oiseau de nuit.'},

 {kind:'Dictée', h:'Dictation: where I live',
  p:'Listen and write exactly what you hear. You can listen again as many times as you like, and use “Plus lentement”.',
  dictee:'I’m originally from Lyon, but at the moment I’m living in Manchester with two friends.',
  why:'Vérifie <i lang="en">originally</i> (deux l), <i lang="en">at the moment</i> et le présent continu <i lang="en">I’m living</i>, qui marque une situation temporaire.'},

 {kind:'Oral', h:'Talk about yourself',
  p:`<p>Imagine you are meeting a new colleague or a new flatmate. Talk about yourself for about one minute: where you are from, what you do, something you are doing at the moment that is different from usual, what you are like (with an example) and what you are into. Tap “Parler”, then “J’ai fini”.</p>`,
  oral:{modele:'Hi, I’m Nora. I’m originally from Fribourg, but I grew up in Zurich, so I speak French and German. I work as a physiotherapist in a sports clinic. At the moment I’m doing an online course in nutrition, so my evenings are quite busy. People say I’m easy-going and patient: I rarely get angry, even when my patients are in a bad mood. But to be honest, I can be a bit stubborn. In my spare time I’m really into hiking, and these days I’m training for a long walk across the Alps next summer.',
   criteres:['I said where I’m from and what I do (present simple)','I talked about something temporary with the present continuous','I used at least two personality adjectives','I gave an example to show what I’m like','I used a ready-made phrase (I’m into…, I tend to…, To be honest…)']}},

 {kind:'Écriture', h:'Your language exchange profile',
  p:'You want to find a partner on a language exchange website. Write your profile (about 120 words): where you come from, what you do, what you are doing these days, what you are like (with an example), your interests, and what kind of partner you are looking for.',
  ecrire:{min:100, modele:'Hi! I’m Léa, I’m 24 and I’m originally from Neuchâtel, in Switzerland. I work as a nurse in a large hospital in Lausanne, so I meet people from all over the world every day. At the moment I’m preparing for a training course in Dublin next summer, which is why I’m trying to improve my English. People say I’m outgoing and reliable: if I promise to call you, I call you! I can be a bit stubborn, though. In my spare time I’m really into climbing, and these days I’m learning to cook Thai food. I’m looking for a partner who wants to practise French in exchange for English. I’m quite flexible, so we can chat online or meet for a coffee. Write to me!',
   criteres:[{t:'I used the present simple for facts or habits (I work, I live, I meet…)', re:'\\b(i|we) (usually |often |always |never |also )?(work|live|study|meet|go|play|like|love|speak|teach)\\b'},{t:'I used the present continuous for something temporary (I’m …ing)', re:'(\\bam|[’\']m) (\\w+ )?\\w+ing\\b'},{t:'I used at least two personality adjectives', re:'\\b(outgoing|sociable|shy|reliable|hard-working|easy-going|easygoing|stubborn|moody|tidy|messy|sensitive|sensible|open-minded|self-confident|patient|calm|ambitious|curious|friendly|generous|honest)\\b[\\s\\S]*\\b(outgoing|sociable|shy|reliable|hard-working|easy-going|easygoing|stubborn|moody|tidy|messy|sensitive|sensible|open-minded|self-confident|patient|calm|ambitious|curious|friendly|generous|honest)\\b'},'I gave an example to show what I’m like',{t:'I said what kind of partner I’m looking for', re:'looking for|would like|[’\']d like|want to find'},'I didn’t write “I am agree”, and I used “currently” (not “actually”) for « actuellement »']}},

 {kind:'Récapitulatif', h:'What to remember',
  p:`<div class="keep"><ul><li><b>Présent simple</b> : faits permanents, habitudes, goûts, vérités générales. <i lang="en">I work as a nurse. She often cooks.</i> Questions et négations avec <i lang="en">do/does</i>.</li><li><b>Présent continu</b> (<i lang="en">am/is/are + -ing</i>) : action en cours, situation temporaire, changement en cours, habitude agaçante avec <i lang="en">always</i>. <i lang="en">At the moment I’m living in London. My English is getting better.</i></li><li><i lang="en">What do you do?</i> = ton métier ; <i lang="en">What are you doing?</i> = maintenant.</li><li><b>Verbes d’état</b> (<i lang="en">know, understand, want, like, belong, seem…</i>) : pas de forme en <i lang="en">-ing</i>. Double sens : <i lang="en">think, have, see, be</i>. <i lang="en">I agree</i>, jamais « I am agree ».</li><li>Personnalité : <i lang="en">easy-going, outgoing, shy, reliable, hard-working, stubborn, moody, open-minded</i>. Faux amis : <i lang="en">sensible</i> = raisonnable, <i lang="en">sensitive</i> = sensible, <i lang="en">nice</i> = sympathique, <i lang="en">actually</i> = en fait, <i lang="en">currently</i> = actuellement.</li><li>Parler de soi : <i lang="en">I’m originally from…, I grew up in…, I work as a…, I’m into…, I tend to…, What I like most about… is…</i></li><li>Accent de mot : re<b>LI</b>able, am<b>BI</b>tious, easy-<b>GO</b>ing ; le <i lang="en">h</i> de <i lang="en">honest</i> est muet.</li></ul></div>`},

 {kind:'Mission', h:'A podcast interview',
  p:'You are listening to “Ordinary Lives”, a podcast about people with unusual routines. The host is talking to Kofi. Listen, then answer the questions one by one. You can listen again at any time.',
  audio:[['Host','Today on Ordinary Lives we’re talking to Kofi, who has two very different jobs. Kofi, what do you do?'],['Kofi','Well, during the week I work as an accountant for a big bank. I sit at a desk, I wear a suit, and I deal with numbers all day.'],['Host','And at the weekend?'],['Kofi','At the weekend I’m a DJ. I play at weddings and birthday parties, mostly in south London.'],['Host','That’s quite a contrast! What are you like as a person, would you say?'],['Kofi','People think I’m serious because of my job, but actually I’m quite outgoing. I just need a bit of time to relax with new people.'],['Host','And what are you working on at the moment?'],['Kofi','These days I’m learning to produce my own music. It’s hard, but I’m getting better every week.']], cache:true,
  parts:[
   {q:'a) What does Kofi do during the week?', opts:['He works as a DJ in south London.','He organises weddings.','He works as an accountant for a bank.','He produces music for other artists.'], ans:2, hint:'Listen to his first answer: “during the week I work as…”.', why:'<i lang="en">During the week I work as an accountant for a big bank</i> : comptable dans une banque. Le week-end, il est DJ.'},
   {q:'b) Why do people think Kofi is serious?', opts:['Because of his job.','Because he never goes to parties.','Because he doesn’t talk to anyone.','Because he wears a suit at weddings.'], ans:0, hint:'He uses the word “because”.', why:'<i lang="en">People think I’m serious because of my job, but actually I’m quite outgoing</i>. Ici, <i lang="en">actually</i> = en fait.'},
   {q:'c) Kofi talks about his progress with the present continuous. Write his sentence.', lab:'His sentence', txt:X('I am getting better every week.','I am getting better.','It is hard, but I am getting better every week.','It’s hard, but I am getting better every week.'), hint:'It starts with “It’s hard, but…”.', why:'<i lang="en">I’m getting better every week</i> : un changement en cours → présent continu.'},
   {q:'d) The host asks you: “So, what do you do?” Answer in English: « Je suis étudiante, mais cette année je fais un stage dans un hôtel. »', lab:'Your answer', txt:X('I am a student, but this year I am doing {an internship|a placement|a work placement|a traineeship} {in|at} a hotel.','I am a student, but I am doing {an internship|a placement|a work placement|a traineeship} {in|at} a hotel this year.'), hint:'Stable situation: present simple of “be”. Temporary situation this year: present continuous.', why:'<i lang="en">I’m a student, but this year I’m doing an internship in a hotel.</i> Le stage est temporaire : présent continu. On dit <i lang="en">do an internship</i> (ou <i lang="en">a work placement</i> en britannique).'}],
  sol:'<p lang="en">Kofi works as an accountant during the week and is a DJ at the weekend. People think he’s serious because of his job, but actually he’s quite outgoing. These days he’s learning to produce his own music, and he’s getting better every week.</p><p>Présent simple pour ses activités stables (<i lang="en">I work, I play, I wear</i>), présent continu pour ce qui est en cours ou temporaire (<i lang="en">I’m learning, I’m getting better</i>). Réponse possible : <i lang="en">I’m a student, but this year I’m doing an internship in a hotel.</i></p>'},

 {kind:'Mission', h:'A room in Brighton',
  p:`<p>You are looking for a room in Brighton and you find this advert. Read it, then answer the questions.</p>
<div class="blk" data-t="Room available"><p lang="en">ROOM AVAILABLE in a friendly flat near the seafront. We’re three people in our late twenties. Hannah is a nurse who works nights, so she sleeps during the day and really appreciates a quiet flat. Oscar is a chef, and he’s always experimenting in the kitchen (you’ll never go hungry!). And I’m Raj, a software developer. I usually work from home, but this month I’m going into the office three days a week because we’re launching a new app. We’re looking for someone tidy, reliable and easy-going who doesn’t mind a bit of noise from the kitchen in the evening. Sorry, no smokers. The rent is £650 a month, plus bills (about £80). Tell us about yourself: what you do, what you’re like and what you’re into!</p></div>`,
  parts:[
   {q:'a) Why does the flat need to be quiet during the day?', opts:['Because Raj works from home every day.','Because Hannah works at night and sleeps during the day.','Because Oscar is studying for his exams.','Because the neighbours complain about noise.'], ans:1, hint:'Read the sentence about Hannah.', why:'<i lang="en">Hannah is a nurse who works nights, so she sleeps during the day</i>.'},
   {q:'b) What is different about Raj’s routine this month?', opts:['He is working nights like Hannah.','He is working from home every day.','He is cooking for the flat every evening.','He is going into the office three days a week.'], ans:3, hint:'Look for the present continuous and “this month”.', why:'<i lang="en">I usually work from home</i> (habitude, présent simple), <i lang="en">but this month I’m going into the office three days a week</i> (situation temporaire, présent continu).'},
   {q:'c) Approximately how much will you pay per month in total, rent and bills?', lab:'Total', unit:'£', ans:730, hint:'Add the rent and the bills.', why:'650 + 80 = 730 £ par mois environ.'},
   {q:'d) In your reply, translate: « En ce moment, je vis chez mes parents. »', lab:'Your sentence', txt:X('{At the moment|Currently|Right now|For the moment|At present}, I am {living|staying} {with my parents|at my parents’|at my parents’ house|at my parents’ place}.','I am {|currently }{living|staying} {with my parents|at my parents’|at my parents’ house|at my parents’ place}{| at the moment| for the moment| right now| at present}.'), hint:'A temporary situation: which present?', why:'<i lang="en">At the moment I’m living with my parents.</i> Situation temporaire → présent continu. « Chez mes parents » = <i lang="en">with my parents</i> (ou <i lang="en">at my parents’</i>).'},
   {q:'e) This sentence from your reply contains a mistake. Write it correctly: <i lang="en">I am agree with your rule about smoking.</i>', lab:'Correct sentence', txt:X('I agree with your rule about smoking.','I totally agree with your rule about smoking.','I completely agree with your rule about smoking.'), hint:'In English, “agree” is already a verb.', why:'<i lang="en">agree</i> est un verbe (et un verbe d’état) : <i lang="en">I agree</i>, sans <i lang="en">am</i>.'}],
  sol:'<p>Hannah travaille de nuit et dort le jour, d’où le calme demandé. Raj travaille d’habitude à la maison (<i lang="en">I usually work from home</i>), mais ce mois-ci il va au bureau trois jours par semaine (<i lang="en">this month I’m going into the office</i>) : habitude au présent simple, exception temporaire au présent continu. Le loyer total est d’environ 650 + 80 = 730 £.</p><p lang="en">Possible reply: Hi Raj! I’m originally from Geneva. At the moment I’m living with my parents, but I’m starting a new job in Brighton next month. I’m tidy and easy-going, and I agree with your rule about smoking!</p>'},
]},

{subj:'en', sem:'b1', id:'en-b1-narrative', o:2, h:'Telling stories', p:'Raconter une histoire vivante et claire : prétérit simple, prétérit continu et past perfect, connecteurs et marqueurs de temps.', steps:[
 {kind:'Écoute', h:'A disastrous trip',
  p:`<p>By the end of this unit, you will be able to tell a story or an anecdote clearly: set the scene, tell the events in order, go back in time when you need to, and link everything with the right words.</p>
<p>Sophie has just come back from a trip to Edinburgh. Her friend Mark asks her how it went. <b>Listen without reading</b>, then answer.</p>
<p><b>Question:</b> why did Sophie miss her flight?</p>`,
  audio:[['Mark','You look exhausted. How was the trip to Edinburgh?'],['Sophie','Don’t ask! It was a disaster from start to finish.'],['Mark','Oh no. What happened?'],['Sophie','Well, I set off for the airport at six, but while I was driving onto the motorway, my car started making a horrible noise.'],['Mark','Did it break down?'],['Sophie','Not right away. I managed to get to a petrol station, and a mechanic who was having his breakfast there kindly had a look. He said it was nothing serious, so I carried on.'],['Mark','So you made it to the airport?'],['Sophie','Yes, but by the time I got there, they had already closed the gate. I’d missed the flight by ten minutes!'],['Mark','You’re joking! What did you do?'],['Sophie','I bought a train ticket instead. It took five hours, but in the end it was lovely. I was sitting next to a woman who had grown up in Edinburgh, and she told me all the best places to visit.']], cache:true,
  opts:['Her car broke down on the motorway.','The flight was cancelled because of the weather.','She arrived after the gate had closed.','She fell asleep at the petrol station.'], ans:2,
  why:'<i lang="en">By the time I got there, they had already closed the gate. I’d missed the flight by ten minutes!</i> La voiture n’est pas tombée en panne : le mécanicien a dit que ce n’était rien de grave. Le <i lang="en">past perfect</i> (<i lang="en">had closed</i>) montre que la porte a été fermée <b>avant</b> son arrivée.'},

 {kind:'Vocabulaire', h:'Words for telling stories',
  p:`<p>Here are phrasal verbs and expressions that make a story come alive. Tap a line to hear it and repeat it. They go into your vocabulary review.</p>`,
  mots:[['to set off','partir, se mettre en route','We set off at six in the morning.'],['to break down','tomber en panne','The car broke down on the motorway.'],['to carry on','continuer','He said it was fine, so I carried on.'],['to manage to (do something)','réussir à, parvenir à','I managed to get to a petrol station.'],['to make it (to)','y arriver, arriver à temps','We made it to the station just in time.'],['to miss (a flight / a train)','rater (un vol, un train)','I missed the flight by ten minutes.'],['to run out of (something)','tomber à court de','My phone ran out of battery.'],['to get lost','se perdre','We got lost in the old town.'],['to turn out (that)','s’avérer (que)','It turned out that the shop was closed.'],['to realise / to realize','se rendre compte','I suddenly realised I’d left my keys inside.'],['all of a sudden','tout à coup','All of a sudden, the lights went out.'],['luckily / fortunately','heureusement','Luckily, a neighbour had a spare key.'],['unfortunately','malheureusement','Unfortunately, it was raining.'],['by the time','le temps que, quand (enfin)','By the time we arrived, the film had started.'],['in the end','finalement, au bout du compte','In the end, it was a great day.'],['You’ll never guess what happened!','Tu ne devineras jamais ce qui s’est passé !'],['Don’t ask!','Ne m’en parle pas !','How was the trip? – Don’t ask!']],
  note:'<b>Attention :</b> <i lang="en">to miss</i> = rater, mais aussi « manquer à » : <i lang="en">I miss you</i> = tu me manques. Et « rater un examen » se dit <i lang="en">to fail an exam</i>, pas <i lang="en">to miss</i>.'},

 {kind:'Pratique', h:'Your turn: all of a sudden',
  p:`<p>Translate into English, using a phrasal verb from the list.</p><p><b>Question:</b> « Tout à coup, ma voiture est tombée en panne. »</p>`, lab:'Your sentence',
  txt:X('{All of a sudden|Suddenly}, my car broke down.','My car {suddenly broke down|broke down all of a sudden}.'),
  why:'<i lang="en">All of a sudden, my car broke down.</i> Un événement terminé dans le récit → prétérit simple (<i lang="en">break, broke, broken</i>). Pas de <i lang="en">has broken</i> : le moment est passé.'},

 {kind:'Grammaire', h:'Past simple and past continuous',
  p:`<p>Sophie raconte : <i lang="en">while I was driving onto the motorway, my car started making a horrible noise</i>. Deux passés dans une seule phrase : le premier plante le décor, le second fait avancer l’histoire.</p>
<div class="def"><p><b>Prétérit simple</b> (<i lang="en">I drove, she didn’t stop, did you see…?</i>) : les actions terminées, les <b>événements principaux</b> du récit, l’un après l’autre. <i lang="en">I set off at six, stopped at a petrol station and carried on.</i></p><p><b>Prétérit continu</b> (<i lang="en">was/were + -ing</i>) : une action <b>en cours</b> à un moment du passé. Il sert à poser le <b>décor</b> (<i lang="en">It was raining. People were waiting.</i>) et à montrer une action <b>interrompue</b> par un événement plus court.</p></div>
<div class="idea"><p>Pense à un film : le prétérit continu est l’arrière-plan qui dure (la pluie, la musique, les gens qui attendent), le prétérit simple, ce sont les actions au premier plan. Avec <i lang="en">when</i>, l’événement court est en général au prétérit simple ; avec <i lang="en">while</i>, l’action longue est au continu : <i lang="en">I was having breakfast when the phone rang. While I was waiting, I read the paper.</i></p></div>
<div class="ex"><p><i lang="en">When the phone rang, I answered it.</i> (deux actions qui se suivent : simple + simple)<br><i lang="en">When the phone rang, I was having a shower.</i> (j’étais déjà sous la douche : simple + continu)</p></div>
<div class="warn"><p>L’imparfait français ne se traduit <b>pas</b> automatiquement par le prétérit continu. Pour un état ou une habitude : <i lang="en">When I was a child, I lived near the sea</i> (« j’habitais »), <i lang="en">I knew the answer</i> (« je savais »). Seule une action en cours devient <i lang="en">was/were + -ing</i>. Et le passé composé se traduit par le prétérit quand le moment est passé : « Hier, j’ai raté le train » = <i lang="en">Yesterday I missed the train</i>, pas <i lang="en">I have missed</i>.</p></div>`,
  audio:'I was having breakfast when the phone rang. When the phone rang, I answered it. While I was waiting, I read the paper.'},

 {kind:'Pratique', h:'Interrupted actions',
  p:`<p>Complete with the past simple or the past continuous of the verb in brackets. Write only the missing words.</p><p><b>Question:</b> <i lang="en">I ___ (walk) home when it started to rain.</i></p>`, lab:'Missing words', txt:['was walking'],
  why:'L’action longue, interrompue par la pluie → prétérit continu : <i lang="en">I was walking home when it started to rain.</i>'},

 {kind:'Pratique', h:'Joining two actions with while',
  p:`<p>Join the two sentences into one, using <b>while</b>.</p><p><b>Question:</b> <i lang="en">I was cooking. The smoke alarm went off.</i></p>`, lab:'Your sentence',
  txt:X('While I was cooking{,|} the smoke alarm went off.','The smoke alarm went off while I was cooking.'),
  why:'<i lang="en">While</i> introduit l’action longue au continu : <i lang="en">While I was cooking, the smoke alarm went off.</i> (ou dans l’autre ordre, sans virgule).'},

 {kind:'Grammaire', h:'The past perfect: going further back',
  p:`<p>Sophie arrive à l’aéroport et découvre que <i lang="en">they had already closed the gate</i>. La porte a été fermée <b>avant</b> son arrivée. Pour remonter ainsi plus loin dans le passé, l’anglais utilise le <i lang="en">past perfect</i>, l’équivalent du plus-que-parfait.</p>
<div class="def"><p><b>Forme</b> : <i lang="en">had</i> + participe passé, à toutes les personnes. <i lang="en">I had left, she hadn’t seen, had you eaten?</i> Contraction : <i lang="en">I’d, she’d, they’d</i> (attention, <i lang="en">’d</i> peut aussi être <i lang="en">would</i>).</p><p><b>Emploi</b> : une action <b>antérieure</b> à un autre moment passé du récit.</p></div>
<div class="idea"><p>Trace une ligne du temps. Le récit avance au prétérit (Sophie arrive). Dès qu’on regarde en arrière depuis ce point (la porte avait été fermée), on passe au <i lang="en">past perfect</i>. Les mots <i lang="en">already, just, by the time, never… before</i> l’accompagnent souvent.</p></div>
<div class="ex"><p><i lang="en">When I got to the station, the train had left.</i> (il était parti avant : je l’ai raté)<br><i lang="en">When I got to the station, the train left.</i> (il est parti à mon arrivée)<br><i lang="en">I didn’t recognise him because he had shaved off his beard.</i><br><i lang="en">It was the first time I had seen the sea.</i></p></div>
<div class="warn"><p>Ne l’emploie pas partout : si les actions sont racontées <b>dans l’ordre</b>, le prétérit suffit (<i lang="en">I got up, had a shower and left</i>). Et vérifie le participe : <i lang="en">had gone, had taken, had eaten</i>, jamais « had went ».</p></div>`,
  audio:'When I got to the station, the train had left. When I got to the station, the train left. It was the first time I had seen the sea.'},

 {kind:'Méthode', h:'Choosing the right past tense',
  p:`<p><b>Quand :</b> pour raconter une histoire, une anecdote, un témoignage. <b>Pourquoi ça marche :</b> chaque temps a un rôle précis dans le récit, comme les plans d’un film : premier plan, arrière-plan, retour en arrière. <b>Comment :</b></p>
<ul><li><b>1. Trouve la chaîne des événements principaux</b> : prétérit simple, dans l’ordre.</li><li><b>2. Repère le décor</b> et les actions en cours à ce moment : prétérit continu.</li><li><b>3. Repère ce qui s’est passé avant</b> le moment raconté : <i lang="en">past perfect</i>.</li><li><b>4. Relie</b> avec <i lang="en">when, while, as soon as, by the time</i>.</li></ul>`,
  demo:{enonce:'Traduis : « Quand Paul est arrivé à la fête, tout le monde dansait, mais Emma était déjà partie. »',
   etapes:[{f:'Événement principal : Paul arrive → <i lang="en">When Paul <b>arrived</b> at the party</i>',w:'C’est le moment raconté : prétérit simple. On dit <i lang="en">arrive <b>at</b></i> pour un lieu précis.'},
    {f:'Décor en cours : tout le monde dansait → <i lang="en">everyone <b>was dancing</b></i>',w:'Une action en cours à ce moment : prétérit continu. <i lang="en">Everyone</i> est singulier : <i lang="en">was</i>, pas <i lang="en">were</i>.'},
    {f:'Avant son arrivée : Emma part → <i lang="en">Emma <b>had already left</b></i>',w:'Le départ d’Emma est antérieur au moment raconté : <i lang="en">past perfect</i>, avec <i lang="en">already</i> entre <i lang="en">had</i> et le participe.'}],
   conclusion:'<i lang="en">When Paul arrived at the party, everyone was dancing, but Emma had already left.</i>'}},

 {kind:'Pratique', h:'Already gone',
  p:`<p>Complete with the past perfect of the verb in brackets. Write only the missing words.</p><p><b>Question:</b> <i lang="en">When we got to the cinema, the film ___ (already / start).</i></p>`, lab:'Missing words', txt:['had already started','had started already'],
  why:'Le film a commencé <b>avant</b> notre arrivée → <i lang="en">had already started</i>. <i lang="en">already</i> se place entre <i lang="en">had</i> et le participe.'},

 {kind:'Pratique', h:'Translate: a reason in the past',
  p:`<p>Translate into English.</p><p><b>Question:</b> « Je ne l’ai pas reconnu parce qu’il s’était rasé la barbe. »</p>`, lab:'Your sentence',
  txt:X('I did not {recognise|recognize} him because he {had|’d} {shaved his beard|shaved off his beard|shaved his beard off}.'),
  why:'<i lang="en">I didn’t recognise him because he had shaved off his beard.</i> Le rasage est antérieur à la rencontre → <i lang="en">past perfect</i>. « Je ne l’ai pas reconnu » : moment passé → prétérit.'},

 {kind:'Pratique', h:'By the time…',
  p:`<p>Put the words in the right order.</p><p><b>Question:</b> what had happened when the police arrived?</p>`,
  ordre:['By the time','the police','arrived,','the thieves','had','disappeared.'], alt:['the thieves had disappeared by the time the police arrived'],
  why:'<i lang="en">By the time the police arrived, the thieves had disappeared.</i> <i lang="en">By the time</i> + prétérit, puis l’action antérieure au <i lang="en">past perfect</i>.'},

 {kind:'Pratique', h:'The French imperfect trap',
  p:`<p>Translate into English. Think: is it an action in progress, or a state / a habit?</p><p><b>Question:</b> « Quand j’étais enfant, j’habitais près de la mer. »</p>`, lab:'Your sentence',
  txt:X('When I was {a child|a kid|little|young|small}, I {lived|used to live} {near the sea|by the sea|close to the sea|next to the sea|near the coast|on the coast|by the seaside|near the seaside|at the seaside}.','I {lived|used to live} {near the sea|by the sea|close to the sea|next to the sea|near the coast|on the coast|by the seaside|near the seaside|at the seaside} when I was {a child|a kid|little|young|small}.'),
  why:'Un état qui a duré, pas une action en cours : <i lang="en">When I was a child, I lived near the sea.</i> (« I was living » serait étrange ici.) Tu verras plus tard <i lang="en">used to</i>, aussi possible.'},

 {kind:'Grammaire', h:'Linking words and time expressions',
  p:`<p>Une bonne histoire ne se contente pas d’aligner les verbes : elle guide l’auditeur dans le temps. Ces mots sont simples, mais plusieurs piègent les francophones.</p>
<div class="def"><ul><li><b>En même temps</b> : <i lang="en">when</i> (quand), <i lang="en">while</i> ou <i lang="en">as</i> (pendant que), <i lang="en">meanwhile</i> (pendant ce temps).</li><li><b>Ensuite</b> : <i lang="en">first, then, after that, afterwards, later, the next morning</i> ; <i lang="en">as soon as</i> (dès que) ; <i lang="en">by the time</i> (le temps que, au moment où… déjà).</li><li><b>Début et fin</b> : <i lang="en">at first</i> (au début, avant que ça change), <i lang="en">in the end</i> (finalement, au bout du compte), <i lang="en">at the end of</i> + nom (à la fin de), <i lang="en">eventually</i> (finalement, après une longue attente), <i lang="en">finally</i> (enfin).</li><li><b>Commentaire</b> : <i lang="en">luckily, unfortunately, all of a sudden, it turned out that…</i></li></ul></div>
<div class="ex"><p><i lang="en">At first I hated the city, but in the end I stayed ten years.</i><br><i lang="en">We waited for hours, and eventually the bus came.</i><br><i lang="en">As soon as I saw her, I knew something was wrong.</i><br><i lang="en">At the end of the film, everyone was crying.</i></p></div>
<div class="warn"><p>« Pendant » a trois traductions : <i lang="en">during</i> + nom (<i lang="en">during the film</i>), <i lang="en">while</i> + sujet et verbe (<i lang="en">while I was watching the film</i>), <i lang="en">for</i> + durée (<i lang="en">for two hours</i>). <i lang="en">Eventually</i> ne veut jamais dire « éventuellement » (= <i lang="en">possibly</i>). Et pour « après, on est allés… », dis <i lang="en">after that</i> ou <i lang="en">afterwards</i>, pas <i lang="en">after</i> tout seul.</p></div>`},

 {kind:'Pratique', h:'During, while or for?',
  p:`<p>Complete with <b>during</b>, <b>while</b> or <b>for</b>.</p><p><b>Question:</b> <i lang="en">My phone rang three times ___ the meeting.</i></p>`, lab:'Missing word', txt:['during'],
  why:'<i lang="en">the meeting</i> est un nom → <i lang="en">during</i>. Avec un sujet et un verbe, ce serait <i lang="en">while we were having the meeting</i> ; avec une durée, <i lang="en">for an hour</i>.'},

 {kind:'Pratique', h:'Finally, after a long time',
  p:`<p>Complete with one word meaning « finalement, au bout d’un long moment ». Careful with false friends!</p><p><b>Question:</b> <i lang="en">We waited for the bus for almost an hour, and ___ it arrived.</i></p>`, lab:'Missing word', txt:['eventually','finally'],
  why:'<i lang="en">eventually</i> (ou <i lang="en">finally</i>) = finalement, après une longue attente. Rappel : <i lang="en">eventually</i> ne veut pas dire « éventuellement ».'},

 {kind:'Prononciation', h:'Weak forms: was, were, had',
  p:`<p>Dans une phrase, les petits mots grammaticaux ne sont pas accentués : ils se réduisent. Si tu prononces <i lang="en">was</i> et <i lang="en">were</i> en entier à chaque fois, ton anglais sonne haché, et surtout tu ne les reconnais pas à l’écoute.</p>
<div class="def"><ul><li><i lang="en">was</i> : forme faible /wəz/ dans <i lang="en">I was waiting</i> ; forme forte /wɒz/ seulement en fin de phrase ou pour insister : <i lang="en">Yes, I was.</i></li><li><i lang="en">were</i> : /wə/ dans <i lang="en">They were watching TV</i> ; /wɜː/ dans <i lang="en">Yes, we were.</i></li><li><i lang="en">had</i> : /əd/, ou contracté en <i lang="en">’d</i>, dans <i lang="en">She’d already left</i>.</li></ul></div>
<div class="warn"><p>Les négations gardent toujours la forme forte : <i lang="en">wasn’t</i> /ˈwɒz.ənt/, <i lang="en">weren’t</i> /wɜːnt/, <i lang="en">hadn’t</i> /ˈhæd.ənt/. À l’écoute, le <i lang="en">’d</i> de <i lang="en">I’d left</i> est presque inaudible : c’est le participe (<i lang="en">left</i>) qui te dit qu’il s’agit d’un <i lang="en">past perfect</i>.</p></div>`,
  audio:'I was waiting for the bus. They were watching TV. She’d already left. Yes, I was. No, they weren’t.'},

 {kind:'Oral', h:'Repeat: weak forms',
  p:`<p>Listen, then say the sentence. Keep <i lang="en">was</i> and <i lang="en">’d</i> short and light, and stress the important words: <i lang="en">While I was <b>WAI</b>ting for the <b>BUS</b>, I re<b>A</b>lised I’d <b>LEFT</b> my <b>PHONE</b> at <b>HOME</b>.</i></p>`,
  dire:'While I was waiting for the bus, I realised I’d left my phone at home.'},

 {kind:'Lecture', h:'Locked out',
  p:`<p>Read this story from a blog, then answer. You can also listen to it.</p>
<div class="blk" data-t="Blog: The worst morning of my life"><p lang="en">Last winter I had a job interview in the centre of Bristol at nine o’clock. I had prepared everything the night before: my best shirt, my CV and a list of questions. In the morning I got up early, had a quick breakfast and left the flat at eight. It was only when I was walking to the bus stop that I realised I had left my phone, my wallet and my keys on the kitchen table. I ran back, but of course the door was locked. My flatmate had gone to work and wasn’t answering the door. Luckily, a neighbour who was walking his dog lent me some money for the bus. By the time I arrived, the interview had already started, so I apologised and explained what had happened. To my surprise, the manager laughed and said, “At least you’re honest!” In the end, I got the job. And these days, before I leave the house, I always say three words out loud: phone, wallet, keys.</p></div>
<p><b>Question:</b> why was the writer late for the interview?</p>`,
  audio:'Last winter I had a job interview in the centre of Bristol at nine o’clock. I had prepared everything the night before: my best shirt, my CV and a list of questions. In the morning I got up early, had a quick breakfast and left the flat at eight. It was only when I was walking to the bus stop that I realised I had left my phone, my wallet and my keys on the kitchen table. I ran back, but of course the door was locked. My flatmate had gone to work and wasn’t answering the door. Luckily, a neighbour who was walking his dog lent me some money for the bus. By the time I arrived, the interview had already started, so I apologised and explained what had happened. To my surprise, the manager laughed and said, “At least you’re honest!” In the end, I got the job. And these days, before I leave the house, I always say three words out loud: phone, wallet, keys.',
  opts:['The bus broke down on the way to the city centre.','The writer got up late and missed the bus.','The flatmate had taken the writer’s keys by mistake.','The writer had left everything inside and had to borrow money for the bus.'], ans:3,
  why:'<i lang="en">I realised I had left my phone, my wallet and my keys on the kitchen table</i>, puis <i lang="en">a neighbour… lent me some money for the bus</i>. L’auteur s’est levé tôt (<i lang="en">I got up early</i>).'},

 {kind:'Dictée', h:'Dictation: the last train',
  p:'Listen and write exactly what you hear. You can listen again as many times as you like, and use “Plus lentement”.',
  dictee:'By the time we got to the station, the last train had already left.',
  why:'<i lang="en">By the time</i> + prétérit (<i lang="en">got</i>), puis le <i lang="en">past perfect</i> pour l’action antérieure : <i lang="en">had already left</i>.'},

 {kind:'Oral', h:'Tell a story',
  p:`<p>Tell a short story (about one minute) about a time when something went wrong: a journey, a lost object, a misunderstanding. Set the scene with the past continuous, tell the main events in the past simple, and use the past perfect at least once. Tap “Parler”, then “J’ai fini”.</p>`,
  oral:{modele:'A few years ago, I was travelling to Milan for a friend’s birthday. It was late at night and the train was almost empty. I was reading a book when the train suddenly stopped in the middle of nowhere. At first nobody explained anything. After about an hour, a guard told us that a tree had fallen onto the line. By the time we arrived in Milan, it was three in the morning and my friend had gone to bed. Luckily, his flatmate was still awake, so she let me in. In the end, we celebrated the next day, and now it’s a funny story we tell at every party.',
   criteres:['I set the scene with the past continuous (was/were + -ing)','I told the main events in the past simple','I used the past perfect at least once (had + participle)','I used linking words (at first, then, by the time, in the end…)','I said how the story ended']}},

 {kind:'Écriture', h:'A day I’ll never forget',
  p:'A travel website is running a story competition: “A day I’ll never forget”. Write your story (about 120 words). Set the scene, tell what happened, go back in time at least once with the past perfect, use at least three linking words, and say how it ended.',
  ecrire:{min:100, modele:'It was a hot Saturday in July, and my friends and I were cycling along Lake Geneva. We had planned a picnic on a small beach near Rolle. While we were riding through a vineyard, my front tyre suddenly exploded. Unfortunately, nobody had brought a repair kit, and the nearest town was ten kilometres away. At first we didn’t know what to do. Then an old farmer who was working in the vines came over and offered to help. He took us to his barn, fixed the tyre in five minutes and even gave us a bottle of his own grape juice. By the time we reached the beach, the others had eaten all the sandwiches! In the end, though, it was one of the best days of the summer.',
   criteres:[{t:'I used the past continuous to set the scene (was/were + -ing)', re:'\\b(was|were) \\w+ing\\b'},{t:'I used the past perfect (had + participle)', re:'\\bhad (already |just |never |not )?(been|gone|left|seen|done|made|eaten|taken|brought|forgotten|lost|fallen|broken|given|told|\\w+ed)\\b|\\bhadn[’\']t \\w+'},{t:'I used at least three linking words', re:'(\\b(when|while|then|after that|afterwards|by the time|as soon as|at first|in the end|eventually|finally|suddenly|unfortunately|luckily|fortunately)\\b[\\s\\S]*){3}'},'I set the scene: when, where, who, the weather','I said how the story ended','I checked my irregular verbs (went, gone, left, ate, eaten…)']}},

 {kind:'Récapitulatif', h:'What to remember',
  p:`<div class="keep"><ul><li><b>Prétérit simple</b> : les événements principaux, terminés, dans l’ordre. <i lang="en">I set off, stopped and carried on.</i> Le passé composé français devient souvent un prétérit : <i lang="en">Yesterday I missed the train.</i></li><li><b>Prétérit continu</b> (<i lang="en">was/were + -ing</i>) : le décor et l’action en cours, souvent interrompue. <i lang="en">I was driving when the car started making a noise.</i> L’imparfait d’un état ou d’une habitude reste au prétérit simple : <i lang="en">When I was a child, I lived near the sea.</i></li><li><b>Past perfect</b> (<i lang="en">had</i> + participe) : ce qui s’est passé <b>avant</b> le moment raconté. <i lang="en">By the time I got there, they had closed the gate.</i> Inutile si les actions sont dans l’ordre.</li><li>Connecteurs : <i lang="en">when, while, as soon as, by the time, at first, then, after that / afterwards, in the end, at the end of…, eventually</i> (≠ éventuellement).</li><li>« Pendant » : <i lang="en">during</i> + nom, <i lang="en">while</i> + proposition, <i lang="en">for</i> + durée.</li><li>Expressions : <i lang="en">set off, break down, carry on, run out of, make it, turn out, get lost, all of a sudden, Don’t ask!</i></li><li>Formes faibles : <i lang="en">was</i> /wəz/, <i lang="en">were</i> /wə/, <i lang="en">’d</i> ; formes fortes en fin de phrase et dans les négations.</li></ul></div>`},

 {kind:'Mission', h:'A witness statement',
  p:'There has been a robbery at a jewellery shop in the town centre. A police officer is interviewing a witness, Mrs Patel. Listen, then answer the questions one by one. You can listen again at any time.',
  audio:[['Officer','So, Mrs Patel, can you tell me exactly what you saw?'],['Mrs Patel','Yes. It was about half past ten. I was waiting at the bus stop opposite the bank, and it was raining quite heavily.'],['Officer','Go on.'],['Mrs Patel','A young man on a scooter stopped outside the jewellery shop. He was wearing a black helmet, so I didn’t see his face. He went inside, and about two minutes later he came running out with a bag.'],['Officer','Did anyone try to stop him?'],['Mrs Patel','No. By the time the shop assistant came out, he had already driven off towards the station.'],['Officer','Did you notice anything else?'],['Mrs Patel','Yes, actually. He had dropped a glove on the pavement. I picked it up and kept it for you.']], cache:true,
  parts:[
   {q:'a) Where was Mrs Patel when it happened?', opts:['Inside the jewellery shop','At the bus stop opposite the bank','At the station','In a café next to the bank'], ans:1, hint:'Listen to the beginning: “I was waiting at…”.', why:'<i lang="en">I was waiting at the bus stop opposite the bank</i> : le décor, au prétérit continu.'},
   {q:'b) Why didn’t she see the man’s face?', opts:['It was too dark.','He was wearing a black helmet.','He was standing behind a bus.','She wasn’t wearing her glasses.'], ans:1, hint:'What was he wearing?', why:'<i lang="en">He was wearing a black helmet, so I didn’t see his face.</i>'},
   {q:'c) Complete: <i lang="en">By the time the shop assistant came out, the man ___ (already / drive) off.</i> Write only the missing words.', lab:'Missing words', txt:['had already driven','had driven'], hint:'The man left before the assistant came out. Participle of “drive”: driven.', why:'L’action est antérieure à la sortie de l’employé → <i lang="en">had already driven off</i> (<i lang="en">drive, drove, driven</i>).'},
   {q:'d) Write the police report sentence in English: « Il avait laissé tomber un gant sur le trottoir. »', lab:'Your sentence', txt:X('He {had|’d} dropped a glove on the {pavement|sidewalk|ground}.'), hint:'He dropped it before Mrs Patel picked it up: use had + participle.', why:'<i lang="en">He had dropped a glove on the pavement.</i> (<i lang="en">pavement</i> en britannique, <i lang="en">sidewalk</i> en américain.)'}],
  sol:'<p lang="en">At about 10.30, while Mrs Patel was waiting at the bus stop in the rain, a man in a black helmet stopped his scooter outside the jewellery shop, went in and came out two minutes later with a bag. By the time the shop assistant came out, he had already driven off. He had dropped a glove on the pavement.</p><p>Le décor est au prétérit continu (<i lang="en">was waiting, was raining, was wearing</i>), les événements au prétérit simple (<i lang="en">stopped, went, came out</i>), et ce qui s’est passé avant au <i lang="en">past perfect</i> (<i lang="en">had driven off, had dropped</i>).</p>'},

 {kind:'Mission', h:'A wedding to remember',
  p:`<p>Your friend Tom has sent you this message. Read it, then answer the questions.</p>
<div class="blk" data-t="Message from Tom"><p lang="en">Hi! You won’t believe what happened at my cousin’s wedding on Saturday. The ceremony was outdoors, in a beautiful garden by the sea. Everything was going perfectly: the sun was shining, the musicians were playing and the guests were chatting happily. Then, just as the bride was walking down the aisle, a seagull landed on the cake and started eating it! At first nobody moved. Eventually the best man chased it away, but by then it had eaten most of the top layer. The bride, who had spent weeks choosing that cake, burst out laughing. In the end, we ate what was left, and it was delicious. Write soon and tell me about your weekend! Tom</p></div>`,
  parts:[
   {q:'a) What was happening when the seagull landed on the cake?', opts:['The guests were eating the cake.','The bride was walking down the aisle.','The musicians were packing up.','It was starting to rain.'], ans:1, hint:'Look for “just as”.', why:'<i lang="en">just as the bride was walking down the aisle, a seagull landed on the cake</i> : action en cours (continu) interrompue par un événement (simple).'},
   {q:'b) Why was most of the top layer missing?', opts:['The bride had cut it too early.','The best man had dropped it.','The seagull had already eaten it.','The guests had eaten it before the ceremony.'], ans:2, hint:'Look at the sentence with “by then”.', why:'<i lang="en">by then it had eaten most of the top layer</i> : <i lang="en">past perfect</i>, la mouette avait déjà mangé avant d’être chassée.'},
   {q:'c) Which word in the message means « finalement, au bout d’un moment » and is a false friend for French speakers?', lab:'The word', txt:['eventually'], hint:'It looks like a French word that means “possibly”.', why:'<i lang="en">Eventually</i> = finalement, après un moment. « Éventuellement » se dit <i lang="en">possibly</i>.'},
   {q:'d) Start your reply. Translate: « Pendant que je lisais ton message, j’ai éclaté de rire. »', lab:'Your sentence', txt:X('While I was reading your {message|email|e-mail}, I {burst out laughing|started laughing|started to laugh|burst into laughter}.','I {burst out laughing|started laughing|started to laugh|burst into laughter} while I was reading your {message|email|e-mail}.'), hint:'“While” + past continuous for the long action; past simple for the short one. “Éclater de rire” is in Tom’s message.', why:'<i lang="en">While I was reading your message, I burst out laughing.</i> (<i lang="en">burst</i> est invariable : <i lang="en">burst, burst, burst</i>.)'},
   {q:'e) Tell Tom about your weekend. Translate: « Quand je suis arrivé à la fête, la plupart des invités étaient déjà partis. »', lab:'Your sentence', txt:X('When I {arrived at|got to|reached} the party{,|} most {of the |}guests had already {left|gone}.','When I {arrived at|got to|reached} the party{,|} most {of the |}guests had {left|gone} already.','Most {of the |}guests had already {left|gone} when I {arrived at|got to|reached} the party.'), hint:'The guests left before you arrived.', why:'<i lang="en">When I arrived at the party, most of the guests had already left.</i> Arrivée au prétérit, départ antérieur au <i lang="en">past perfect</i>.'}],
  sol:'<p>Le décor est au prétérit continu (<i lang="en">the sun was shining, the musicians were playing</i>), l’événement qui l’interrompt au prétérit simple (<i lang="en">a seagull landed</i>), et ce qui précède au <i lang="en">past perfect</i> (<i lang="en">it had eaten, she had spent weeks</i>). <i lang="en">Eventually</i> = finalement.</p><p lang="en">Possible reply: While I was reading your message, I burst out laughing! My weekend was less exciting: when I arrived at the party on Saturday, most of the guests had already left.</p>'},
]},

{subj:'en', sem:'b1', id:'en-b1-achievements', o:3, h:'Achievements', p:'Parler de ses réussites, de son parcours et des projets en cours : present perfect simple et continu, for et since, How long…?, et le contraste avec le prétérit.', steps:[
 {kind:'Écoute', h:'It’s been ages!',
  p:`<p>By the end of this unit, you will be able to talk about what you have achieved, what you have been doing lately and how long you have been doing it, and to tell the difference between “finished” past and past linked to now.</p>
<p>Leila and Dan were at university together. They meet by chance in the street, years later. <b>Listen without reading</b>, then answer.</p>
<p><b>Question:</b> what has Dan done since he left the bank?</p>`,
  audio:[['Leila','Dan? I don’t believe it! I haven’t seen you since our graduation!'],['Dan','Leila! Wow, it’s been at least six years. How are you?'],['Leila','I’m great, thanks. I’ve just come back from Canada, actually. I’ve been working in Vancouver for the last three years.'],['Dan','Really? Doing what?'],['Leila','I’ve been teaching French in a secondary school. I’ve loved every minute of it. What about you? Are you still working at the bank?'],['Dan','No, I left in 2022. I’ve set up my own business: we make bikes from bamboo.'],['Leila','Bamboo bikes? That’s amazing! How’s it going?'],['Dan','Better than I expected. We’ve sold about four hundred so far, and we’ve just won a prize for sustainable design.'],['Leila','Congratulations! You look a bit tired, though.'],['Dan','Yes, I’ve been working seventy hours a week since January. But I’m not complaining!']], cache:true,
  opts:['He has been teaching in a school in Canada.','He has set up a company that makes bamboo bikes.','He has won a cycling race.','He has gone back to university.'], ans:1,
  why:'<i lang="en">I left in 2022. I’ve set up my own business: we make bikes from bamboo.</i> Remarque les deux temps : <i lang="en">I left in 2022</i> (date terminée, prétérit) et <i lang="en">I’ve set up</i> (résultat qui compte aujourd’hui, <i lang="en">present perfect</i>). C’est Leila qui a enseigné au Canada.'},

 {kind:'Vocabulaire', h:'Talking about achievements',
  p:`<p>Here are collocations to talk about success, progress and projects. Learn them as blocks: in English we <i lang="en">make</i> progress and <i lang="en">set up</i> a business. Tap a line to hear it.</p>`,
  mots:[['to achieve (a goal)','atteindre (un objectif), réaliser','She achieved her goal of running a marathon.'],['an achievement','une réussite, un accomplissement','Learning to swim at forty was a real achievement.'],['to pass an exam','réussir un examen','Great news: I’ve passed my driving test!'],['to take an exam / to sit an exam','passer un examen','I’m taking my final exam on Monday.'],['to fail (an exam)','échouer à, rater (un examen)','He failed the first time, but he passed the second time.'],['to set up (a business)','créer, monter (une entreprise)','Dan has set up his own business.'],['to be promoted / to get a promotion','obtenir une promotion','She’s just been promoted to manager.'],['to make progress','faire des progrès','You’ve made a lot of progress this year.'],['to take up (a hobby)','se mettre à (une activité)','I’ve taken up yoga.'],['to graduate (from)','obtenir son diplôme','He graduated from university in 2021.'],['to raise money (for)','récolter des fonds (pour)','We’ve raised £2,000 for the hospital.'],['to be proud of','être fier de','I’m really proud of you.'],['so far','jusqu’ici, pour l’instant','We’ve sold four hundred bikes so far.'],['lately / recently','ces derniers temps, récemment','What have you been doing lately?'],['to come a long way','faire beaucoup de chemin, beaucoup progresser','You’ve come a long way since your first lesson.'],['It’s been ages!','Ça fait une éternité !','Leila! It’s been ages!'],['Congratulations (on…)!','Félicitations (pour…) !','Congratulations on your new job!']],
  note:'<b>Pièges :</b> « passer un examen » = <i lang="en">take</i> (ou <i lang="en">sit</i>) <i lang="en">an exam</i> ; <i lang="en">pass an exam</i> = le réussir. <i lang="en">progress</i> est indénombrable : <i lang="en">a lot of progress</i>, jamais « progresses ». Et on dit <i lang="en">Congratulations <b>on</b></i>, pas <i lang="en">for</i>.'},

 {kind:'Pratique', h:'Your turn: good news',
  p:`<p>Translate into English. Be careful with « réussir un examen ».</p><p><b>Question:</b> « Bonne nouvelle : j’ai réussi mon examen de conduite ! »</p>`, lab:'Your sentence',
  txt:X('{Good|Great} news: I have passed my driving {test|exam}!','{Good|Great} news: I passed my driving {test|exam}!'),
  why:'<i lang="en">I’ve passed my driving test!</i> (nouvelle toute fraîche, résultat présent). <i lang="en">pass</i> = réussir ; « passer » se dirait <i lang="en">take</i>. En britannique, on dit plutôt <i lang="en">driving test</i>.'},

 {kind:'Grammaire', h:'The present perfect simple',
  p:`<p>Dan dit <i lang="en">We’ve sold about four hundred so far</i>, mais <i lang="en">I left in 2022</i>. Les deux actions sont passées ; pourtant l’anglais emploie deux temps différents. La différence : le lien avec le présent.</p>
<div class="def"><p><b>Forme</b> : <i lang="en">have/has</i> + participe passé. <i lang="en">I’ve finished, she hasn’t called, have you ever been…?</i></p><p><b>Emplois</b> :</p><ul><li><b>une expérience</b> dans la vie jusqu’à maintenant, sans date : <i lang="en">I’ve been to Canada. Have you ever run a marathon?</i></li><li><b>un résultat présent</b> d’une action passée, souvent récente, avec <i lang="en">just, already, yet</i> : <i lang="en">I’ve lost my keys</i> (je ne les ai plus) ; <i lang="en">We’ve just won a prize.</i></li><li><b>une période pas encore terminée</b> : <i lang="en">today, this year, so far, since…, for…</i> : <i lang="en">We’ve sold 400 bikes so far.</i></li></ul></div>
<div class="idea"><p>Le <i lang="en">present perfect</i> regarde le passé <b>depuis maintenant</b> : ce qui compte, c’est le bilan aujourd’hui. Le prétérit raconte un moment <b>terminé et situé</b>. Si tu peux répondre à la question « quand exactement&nbsp;? », c’est le prétérit.</p></div>
<div class="ex"><p><i lang="en">I’ve worked in three countries.</i> (bilan de ma vie) / <i lang="en">I worked in Spain in 2020.</i> (moment précis)<br><i lang="en">Have you finished your report yet?</i> – <i lang="en">Yes, I finished it this morning.</i></p></div>
<div class="warn"><p>Le passé composé ne se traduit pas toujours par le <i lang="en">present perfect</i>. Avec un moment passé précis (<i lang="en">yesterday, last year, in 2021, two days ago, when I was ten</i>), c’est le prétérit : « J’ai fini l’université en 2021 » = <i lang="en">I finished university in 2021</i>. À l’oral, <i lang="en">she’s finished</i> = <i lang="en">she <b>has</b> finished</i> (le participe te le dit), alors que <i lang="en">she’s tired</i> = <i lang="en">she <b>is</b> tired</i>.</p></div>`,
  audio:'I’ve worked in three countries. I worked in Spain in 2020. Have you finished your report yet? Yes, I finished it this morning.'},

 {kind:'Pratique', h:'Present perfect or past simple?',
  p:`<p>This sentence contains a mistake. Write the correct sentence.</p><p><b>Question:</b> <i lang="en">I have finished university in 2021.</i></p>`, lab:'Correct sentence',
  txt:X('I finished university in 2021.','I graduated {from university |}in 2021.','I left university in 2021.'),
  why:'<i lang="en">in 2021</i> est un moment terminé → prétérit : <i lang="en">I finished university in 2021</i> (ou <i lang="en">I graduated in 2021</i>).'},

 {kind:'Pratique', h:'Results and numbers',
  p:`<p>Complete with the present perfect simple of the verb in brackets. Write only the missing words.</p><p><b>Question:</b> <i lang="en">This month I ___ (read) three books, and I’m starting a fourth one.</i></p>`, lab:'Missing words', txt:['have read'],
  why:'Un bilan chiffré sur une période pas terminée (<i lang="en">this month</i>) → <i lang="en">I’ve read</i> (<i lang="en">read, read, read</i>, prononcé /red/ au participe).'},

 {kind:'Grammaire', h:'The present perfect continuous, for and since',
  p:`<p>Leila dit <i lang="en">I’ve been working in Vancouver for the last three years</i>, et Dan <i lang="en">I’ve been working seventy hours a week since January</i>. Ces activités ont commencé dans le passé et durent encore, ou viennent tout juste de s’arrêter. C’est le <i lang="en">present perfect continuous</i>, la traduction la plus fréquente de « depuis ».</p>
<div class="def"><p><b>Forme</b> : <i lang="en">have/has been + -ing</i>. <i lang="en">I’ve been waiting, she hasn’t been sleeping well, how long have you been learning…?</i></p><p><b>Emplois</b> : une activité qui dure <b>jusqu’à maintenant</b>, quand on insiste sur la durée ; une activité <b>qui vient de s’arrêter</b> et dont on voit le résultat (<i lang="en">You look tired. – I’ve been running.</i>).</p><p><b>for</b> + une durée (<i lang="en">for three years, for ages, for the last six months</i>) ; <b>since</b> + un point de départ (<i lang="en">since January, since 2019, since I was ten</i>).</p></div>
<div class="idea"><p>Le français dit « j’habite ici depuis cinq ans » au présent, parce qu’il regarde la situation actuelle. L’anglais regarde toute la période, du début jusqu’à maintenant : il lui faut un <i lang="en">present perfect</i>. <i lang="en">I’ve lived here for five years</i> ou <i lang="en">I’ve been living here for five years</i>.</p></div>
<div class="ex"><p><i lang="en">How long have you been learning English?</i> – <i lang="en">For three years. / Since 2023.</i><br><i lang="en">Why are your hands dirty?</i> – <i lang="en">I’ve been gardening.</i><br><i lang="en">I’ve known Sarah for ten years.</i> (verbe d’état : pas de forme continue)</p></div>
<div class="warn"><p>Les trois erreurs typiques des francophones : « I live here since 2019 » (il faut <i lang="en">I’ve lived</i> ou <i lang="en">I’ve been living here since 2019</i>), « since three years » (il faut <i lang="en">for three years</i>), et « Since when do you…? » pour « depuis combien de temps » (on dit <i lang="en">How long have you been…?</i>). Ne confonds pas non plus avec « il y a » : <i lang="en">I started three years ago</i> (prétérit + <i lang="en">ago</i>).</p></div>`,
  audio:'How long have you been learning English? For three years. Why are your hands dirty? I’ve been gardening. I’ve known Sarah for ten years.'},

 {kind:'Méthode', h:'Simple, continuous or past simple?',
  p:`<p><b>Quand :</b> dès que tu parles d’une action passée liée au présent, ou d’une durée avec « depuis ». <b>Pourquoi ça marche :</b> chaque forme répond à une question différente : quand&nbsp;? (prétérit) ; combien, quel résultat&nbsp;? (<i lang="en">present perfect simple</i>) ; depuis combien de temps, quelle activité&nbsp;? (<i lang="en">present perfect continuous</i>). <b>Comment :</b></p>
<ul><li><b>1. Un moment passé terminé</b> (<i lang="en">yesterday, in 2024, ago, last…</i>)&nbsp;? → prétérit.</li><li><b>2. Un résultat, un nombre, une expérience</b> (<i lang="en">how many, three chapters, ever, never, already</i>)&nbsp;? → <i lang="en">present perfect simple</i>.</li><li><b>3. Une durée ou une activité en cours</b> (<i lang="en">how long, for, since, all day, lately</i>) avec un verbe d’action&nbsp;? → <i lang="en">present perfect continuous</i>.</li><li><b>4. Un verbe d’état</b> (<i lang="en">know, be, have</i> = posséder, <i lang="en">like</i>)&nbsp;? → simple, même avec <i lang="en">for</i> ou <i lang="en">since</i>.</li></ul>`,
  demo:{enonce:'Traduis : « J’écris mon roman depuis deux ans et j’ai écrit douze chapitres. Je l’ai commencé en 2024. »',
   etapes:[{f:'« depuis deux ans » → <i lang="en">I’<b>ve been writing</b> my novel <b>for</b> two years</i>',w:'Une activité qui dure jusqu’à maintenant, on insiste sur la durée : continu. « deux ans » est une durée → <i lang="en">for</i>.'},
    {f:'« douze chapitres » → <i lang="en">I’<b>ve written</b> twelve chapters</i>',w:'Un résultat chiffré : on compte ce qui est fait → simple (<i lang="en">write, wrote, written</i>).'},
    {f:'« en 2024 » → <i lang="en">I <b>started</b> it in 2024</i>',w:'Une date terminée → prétérit, même si le roman n’est pas fini.'}],
   conclusion:'<i lang="en">I’ve been writing my novel for two years and I’ve written twelve chapters. I started it in 2024.</i>'}},

 {kind:'Pratique', h:'For or since?',
  p:`<p>Complete with <b>for</b> or <b>since</b>.</p><p><b>Question:</b> <i lang="en">My sister has been working in a hospital ___ she left school.</i></p>`, lab:'Missing word', txt:['since'],
  why:'<i lang="en">she left school</i> est un point de départ → <i lang="en">since</i>. Après <i lang="en">since</i>, une proposition se met au prétérit.'},

 {kind:'Pratique', h:'Translate: « depuis »',
  p:`<p>Translate into English. Remember: « depuis » + present in French is not a present in English.</p><p><b>Question:</b> « J’habite à Genève depuis cinq ans. »</p>`, lab:'Your sentence',
  txt:X('I have {lived|been living} in Geneva for {five|5} years.'),
  why:'<i lang="en">I’ve lived in Geneva for five years</i> ou <i lang="en">I’ve been living in Geneva for five years</i>. Durée → <i lang="en">for</i>. Jamais « I live in Geneva since five years ».'},

 {kind:'Pratique', h:'Asking How long…?',
  p:`<p>Translate the question into English.</p><p><b>Question:</b> « Depuis combien de temps apprends-tu l’anglais ? »</p>`, lab:'Your question',
  txt:X('How long have you been {learning|studying} English?','How long have you {learnt|learned|studied} English?'),
  why:'« Depuis combien de temps » = <i lang="en">How long</i> + <i lang="en">present perfect</i>, le plus souvent continu : <i lang="en">How long have you been learning English?</i> Pas de « Since when do you learn ».'},

 {kind:'Pratique', h:'A visible result',
  p:`<p>Your friend’s eyes are red. Ask if she has been crying. Write the whole question with the present perfect continuous of <b>cry</b>.</p><p><b>Question:</b> <i lang="en">Your eyes are red. ___?</i></p>`, lab:'Your question', txt:['Have you been crying?'],
  why:'Une activité qui vient de s’arrêter et dont on voit le résultat → <i lang="en">Have you been crying?</i>'},

 {kind:'Pratique', h:'State verbs again',
  p:`<p>This sentence contains a mistake. Write the correct sentence.</p><p><b>Question:</b> <i lang="en">I’ve been knowing Sarah for ten years.</i></p>`, lab:'Correct sentence', txt:['I have known Sarah for ten years.'],
  why:'<i lang="en">know</i> est un verbe d’état : pas de forme continue, même avec <i lang="en">for</i>. <i lang="en">I’ve known Sarah for ten years.</i>'},

 {kind:'Pratique', h:'So far',
  p:`<p>Put the words in the right order.</p><p><b>Question:</b> how much money has the charity raised?</p>`,
  ordre:['We’ve','raised','two','thousand','pounds','so','far.'], alt:['So far we’ve raised two thousand pounds'],
  why:'<i lang="en">We’ve raised two thousand pounds so far.</i> <i lang="en">so far</i> (jusqu’ici) : la période continue → <i lang="en">present perfect</i>. Il peut aussi ouvrir la phrase.'},

 {kind:'Prononciation', h:'Weak forms: have, has, been',
  p:`<p>Dans <i lang="en">How long have you been waiting?</i>, un anglophone ne prononce pas chaque mot avec la même force. Seuls les mots porteurs de sens sont accentués : <i lang="en">How <b>LONG</b> have you been <b>WAI</b>ting?</i> Les auxiliaires s’effacent, et c’est pour cela qu’on ne les entend pas toujours.</p>
<div class="def"><ul><li><i lang="en">have</i> → /həv/ ou /əv/, contracté <i lang="en">’ve</i> : <i lang="en">I’ve finished</i> /aɪv/.</li><li><i lang="en">has</i> → /həz/ ou /əz/, contracté <i lang="en">’s</i> : <i lang="en">She’s been working</i>.</li><li><i lang="en">been</i> → en anglais britannique, souvent /bɪn/ (comme <i lang="en">bin</i>) plutôt que /biːn/.</li><li><i lang="en">for</i> → /fə/ : <i lang="en">for ages</i> /fər ˈeɪdʒɪz/.</li></ul></div>
<div class="warn"><p>La forme forte revient dans les réponses courtes et en fin de phrase : <i lang="en">Yes, I have</i> /hæv/, <i lang="en">Yes, she has</i> /hæz/. Le <i lang="en">h</i> de <i lang="en">have</i> peut disparaître dans une forme faible au milieu de la phrase, mais jamais dans un mot plein comme <i lang="en">happy</i> ou <i lang="en">house</i>.</p></div>`,
  audio:'How long have you been waiting? I’ve been waiting for ages. She’s been working here since March. Have you finished? Yes, I have.'},

 {kind:'Oral', h:'Repeat: I’ve been working…',
  p:`<p>Listen, then say Leila’s sentence. Keep <i lang="en">I’ve been</i> short and light, and stress the important words: <i lang="en">I’ve been <b>WOR</b>king in Van<b>COU</b>ver for the <b>LAST THREE YEARS</b>.</i></p>`,
  dire:'I’ve been working in Vancouver for the last three years.'},

 {kind:'Lecture', h:'The repair café',
  p:`<p>Read this article from a local newspaper, then answer. You can also listen to it.</p>
<div class="blk" data-t="Local heroes: the woman who fixes everything"><p lang="en">When Marta Novak moved to Leeds in 2019, she was shocked by how much people threw away. “I saw a perfectly good lamp in a bin outside my flat, and I thought, this is crazy,” she says. Two years later, she opened the city’s first repair café in a church hall. The idea is simple: once a month, volunteers fix broken objects for free, while their owners drink tea, watch and learn. Since then, the café has grown enormously. Volunteers have repaired more than three thousand items, from toasters and bicycles to wedding dresses, and around forty people now help regularly. Marta has also given talks in schools and has written a short guide to fixing things at home. “The best part isn’t the repairs,” she explains. “It’s the conversations. People who have lived on the same street for years have met for the first time here.” For the past six months, Marta has been working with the city council on a new project: a “library of things”, where people can borrow tools instead of buying them. It opens next spring.</p></div>
<p><b>Question:</b> which sentence is true about the repair café?</p>`,
  audio:'When Marta Novak moved to Leeds in 2019, she was shocked by how much people threw away. “I saw a perfectly good lamp in a bin outside my flat, and I thought, this is crazy,” she says. Two years later, she opened the city’s first repair café in a church hall. The idea is simple: once a month, volunteers fix broken objects for free, while their owners drink tea, watch and learn. Since then, the café has grown enormously. Volunteers have repaired more than three thousand items, from toasters and bicycles to wedding dresses, and around forty people now help regularly. Marta has also given talks in schools and has written a short guide to fixing things at home. “The best part isn’t the repairs,” she explains. “It’s the conversations. People who have lived on the same street for years have met for the first time here.” For the past six months, Marta has been working with the city council on a new project: a “library of things”, where people can borrow tools instead of buying them. It opens next spring.',
  opts:['Marta repairs all the objects herself.','It charges a small fee for each repair.','It has helped neighbours get to know each other.','It has already opened a library of tools.'], ans:2,
  why:'<i lang="en">People who have lived on the same street for years have met for the first time here.</i> Ce sont des bénévoles qui réparent, c’est gratuit (<i lang="en">for free</i>), et la « bibliothèque d’objets » n’ouvrira qu’au printemps prochain.'},

 {kind:'Pratique', h:'Working out a date',
  p:`<p>Look at the article about Marta again.</p><p><b>Question:</b> in which year did Marta open the first repair café? Write the year.</p>`, lab:'Year', txt:['2021','in 2021'],
  why:'Elle est arrivée en 2019, et <i lang="en">two years later, she opened…</i> : 2019 + 2 = 2021. Une date terminée, donc un prétérit (<i lang="en">opened</i>) ; le bilan d’aujourd’hui, lui, est au <i lang="en">present perfect</i> (<i lang="en">have repaired</i>).'},

 {kind:'Dictée', h:'Dictation: the piano',
  p:'Listen and write exactly what you hear. You can listen again as many times as you like, and use “Plus lentement”.',
  dictee:'I’ve been learning the piano for two years, and I’ve just passed my first exam.',
  why:'Durée qui continue : <i lang="en">I’ve been learning… for two years</i>. Résultat tout récent : <i lang="en">I’ve just passed</i>. Les deux <i lang="en">’ve</i> sont faibles : écoute bien.'},

 {kind:'Oral', h:'Something you’re proud of',
  p:`<p>Talk for about one minute about something you are proud of, and something you have been working on lately. Say when you started, how long you have been doing it and what you have achieved so far. Tap “Parler”, then “J’ai fini”.</p>`,
  oral:{modele:'Something I’m really proud of is my first half marathon. I’ve never been very sporty, but two years ago I took up running with a friend. At first I couldn’t run for more than ten minutes. I’ve been training three times a week since then, and last October I finished the race in just over two hours. Lately I’ve been working on something completely different: I’ve been learning Italian, because I’m going to Rome in the summer. I’ve done about forty lessons so far, and I can already order a meal and chat a little.',
   criteres:['I used the past simple with a finished time (two years ago, last October…)','I used the present perfect simple for a result or an experience (I’ve done, I’ve never been…)','I used the present perfect continuous for an activity that continues (I’ve been learning…)','I used for or since correctly','I used a collocation from the unit (take up, make progress, so far…)']}},

 {kind:'Écriture', h:'Catching up with an old friend',
  p:'You have just found an old school friend online. You haven’t seen each other since you left school. Write an email (about 120 words): say what you have done since then (studies, work, travel), what you have been doing lately, one thing you are proud of, and ask two questions.',
  ecrire:{min:100, modele:'Hi Tom,<br>I can’t believe I’ve found you after all these years! It’s been ages since we left school, and so much has happened. After school I studied engineering in Zurich, and I graduated in 2022. Since then I’ve worked for a company that builds solar panels, and last year I got a promotion, which I’m quite proud of. I’ve also travelled a lot: I’ve been to Japan twice and I’ve just come back from Iceland. Lately I’ve been learning to sail on Lake Geneva at the weekends, and I’ve finally got my sailing licence. What about you? What have you been doing since school? Are you still playing the drums?<br>Write soon!<br>Marc',
   criteres:[{t:'I used the present perfect simple (I’ve done, I’ve been to…)', re:'\\b(have|has|[’\']ve|[’\']s) (just |already |never |ever |finally |also |\\w+ly )?(been|done|worked|travelled|traveled|finished|passed|got|gotten|found|made|seen|written|won|learnt|learned|studied|lived|started|taken|\\w+ed)\\b'},{t:'I used the present perfect continuous (I’ve been …ing)', re:'\\b(have|has|[’\']ve|[’\']s) (\\w+ )?been \\w+ing\\b'},{t:'I used the past simple with a finished time (in 2022, last year, … ago)', re:'\\b(in (19|20)\\d\\d|last (year|month|week|summer|winter|spring|autumn)|\\w+ ago|yesterday)\\b'},{t:'I used for or since', re:'\\b(for|since)\\b'},'I said what I’m proud of',{t:'I asked at least two questions', re:'\\?[\\s\\S]*\\?'}]}},

 {kind:'Récapitulatif', h:'What to remember',
  p:`<div class="keep"><ul><li><b>Present perfect simple</b> (<i lang="en">have/has</i> + participe) : expérience (<i lang="en">I’ve been to Canada</i>), résultat présent (<i lang="en">I’ve lost my keys</i>), période non terminée (<i lang="en">so far, this year</i>). Avec <i lang="en">just, already, yet, ever, never</i>.</li><li><b>Prétérit</b> dès qu’il y a un moment passé terminé : <i lang="en">yesterday, last year, in 2021, two years ago, when I was…</i> : <i lang="en">I left in 2022.</i></li><li><b>Present perfect continuous</b> (<i lang="en">have/has been + -ing</i>) : activité qui dure jusqu’à maintenant (<i lang="en">I’ve been working here for three years</i>) ou qui vient de s’arrêter avec un résultat visible (<i lang="en">I’ve been running</i>).</li><li>« depuis » : <i lang="en">for</i> + durée, <i lang="en">since</i> + point de départ ; <i lang="en">How long have you been…?</i> Jamais « I live here since… » ni « since three years ». « il y a » = <i lang="en">ago</i> + prétérit.</li><li>Simple pour compter (<i lang="en">how many, three books</i>) et avec les verbes d’état (<i lang="en">I’ve known her for years</i>) ; continu pour la durée de l’activité.</li><li>Collocations : <i lang="en">pass</i> (réussir) / <i lang="en">take</i> (passer) <i lang="en">an exam, make progress, set up a business, take up a hobby, raise money, Congratulations on…!</i></li><li>Formes faibles : <i lang="en">have</i> /əv/, <i lang="en">has</i> /əz/, <i lang="en">been</i> /bɪn/, <i lang="en">for</i> /fə/ ; forme forte dans <i lang="en">Yes, I have.</i></li></ul></div>`},

 {kind:'Mission', h:'A job interview',
  p:'Claire Moreau is applying for a job as a hotel manager in London. Listen to part of her interview, then answer the questions one by one. You can listen again at any time.',
  audio:[['Interviewer','So, Ms Moreau, tell me about your experience. How long have you been working in hotels?'],['Claire','For about seven years now. I started as a receptionist in Montreux in 2019, and I’ve been assistant manager at a hotel in Lausanne since 2023.'],['Interviewer','And what would you say is your biggest achievement so far?'],['Claire','Last year our online reviews were quite poor, so I introduced a new training programme for the reception team. Since then, our average rating has gone up from three point eight to four point six.'],['Interviewer','Impressive. Have you ever managed a team on your own?'],['Claire','Yes, I have. My manager has been on maternity leave since January, so I’ve been running the hotel on my own for the last four months.'],['Interviewer','And why do you want to leave?'],['Claire','I’ve learnt a lot in Lausanne, but I’d like to work in a bigger hotel, and I’ve always wanted to live in London.']], cache:true,
  parts:[
   {q:'a) How long has Claire been working in hotels?', opts:['For about four years','Since 2023','For about seven years','Since January'], ans:2, hint:'Listen to her first answer.', why:'<i lang="en">For about seven years now. I started as a receptionist in Montreux in 2019.</i> 2023 est l’année où elle est devenue directrice adjointe.'},
   {q:'b) What has happened since Claire introduced the training programme?', opts:['The hotel’s online rating has gone up.','The reception team has doubled.','Her manager has left the hotel.','The hotel has won a prize.'], ans:0, hint:'Listen for “Since then…”.', why:'<i lang="en">Since then, our average rating has gone up from three point eight to four point six.</i>'},
   {q:'c) By how many points has the average rating gone up?', lab:'Points', ans:0.8, tol:0.001, hint:'Subtract the old rating from the new one.', why:'4,6 − 3,8 = 0,8 point.'},
   {q:'d) You are the interviewer. Ask Claire in English: « Depuis combien de temps dirigez-vous l’hôtel seule ? »', lab:'Your question', txt:X('How long have you been {running|managing} the hotel {on your own|alone|by yourself}?','How long have you {run|managed} the hotel {on your own|alone|by yourself}?'), hint:'“Depuis combien de temps” = How long + present perfect (continuous).', why:'<i lang="en">How long have you been running the hotel on your own?</i> Réponse de Claire : <i lang="en">for the last four months</i>, depuis janvier.'}],
  sol:'<p lang="en">Claire has been working in hotels for about seven years: she started in Montreux in 2019 and has been assistant manager in Lausanne since 2023. Since she introduced a training programme, the hotel’s rating has gone up by 0.8 points (from 3.8 to 4.6). She has been running the hotel on her own for four months.</p><p>Prétérit pour les dates terminées (<i lang="en">I started in 2019, last year our reviews were poor</i>), <i lang="en">present perfect</i> pour le bilan et la durée jusqu’à maintenant (<i lang="en">has gone up, I’ve been running, I’ve always wanted</i>).</p>'},

 {kind:'Mission', h:'A project update',
  p:`<p>You gave money to a community garden project. You receive this update by email. Read it, then answer the questions.</p>
<div class="blk" data-t="The Hilltop Community Garden: project update"><p lang="en">Dear supporters, it’s been six months since we launched our crowdfunding campaign, and we wanted to tell you how things are going. Thanks to you, we’ve raised £18,500 so far, which is 74% of our target. We’ve already bought the tools and built twelve raised beds, and local schoolchildren have planted their first vegetables. We haven’t finished the greenhouse yet: the builders have been waiting for the glass since March, and it still hasn’t arrived. Meanwhile, our volunteers have been organising weekly cooking workshops, and more than two hundred people have taken part. We’ve also had some bad news: the council has refused to pay for the water supply, so we need to find another solution. Thank you for your patience and your generosity!</p></div>`,
  parts:[
   {q:'a) What is the total target of the campaign, in pounds?', lab:'Target', unit:'£', ans:25000, hint:'£18,500 is 74% of the target. Divide by 0.74.', why:'18 500 / 0,74 = 25 000 £.'},
   {q:'b) Why isn’t the greenhouse finished?', opts:['The builders have been ill.','The council has refused to pay for it.','The glass still hasn’t arrived.','The volunteers have been too busy with the workshops.'], ans:2, hint:'Read the sentence with “yet”.', why:'<i lang="en">the builders have been waiting for the glass since March, and it still hasn’t arrived</i>. C’est l’eau que la commune refuse de payer.'},
   {q:'c) Translate: « Nous n’avons pas encore trouvé de solution pour l’eau. »', lab:'Your sentence', txt:X('We have not found a solution {for|to} the water{| supply| problem} yet.','We have not yet found a solution {for|to} the water{| supply| problem}.','We still have not found a solution {for|to} the water{| supply| problem}.'), hint:'“pas encore” in a negative sentence = yet, usually at the end.', why:'<i lang="en">We haven’t found a solution for the water yet.</i> <i lang="en">yet</i> se place en fin de phrase négative ; <i lang="en">already</i> s’emploie dans les phrases affirmatives.'},
   {q:'d) A supporter asks: “How long have the builders been waiting for the glass?” Answer in a full sentence with <b>since</b>.', lab:'Your answer', txt:X('They have been waiting {for it|for the glass|} since March.','The builders have been waiting {for it |for the glass |}since March.','Since March.'), hint:'Use the present perfect continuous and the month from the email.', why:'<i lang="en">They’ve been waiting for the glass since March.</i> <i lang="en">March</i> est un point de départ → <i lang="en">since</i>.'},
   {q:'e) Translate for your own post about the project: « Plus de deux cents personnes ont participé aux ateliers jusqu’ici. »', lab:'Your sentence', txt:X('{More than|Over} {two hundred|200} people have {taken part in|participated in|attended} the workshops so far.','So far, {more than|over} {two hundred|200} people have {taken part in|participated in|attended} the workshops.'), hint:'“jusqu’ici” = so far, which goes with the present perfect.', why:'<i lang="en">More than two hundred people have taken part in the workshops so far.</i> <i lang="en">so far</i> → <i lang="en">present perfect</i> (<i lang="en">take, took, taken</i>).'}],
  sol:'<p>18 500 £ représentent 74 % de l’objectif : 18 500 / 0,74 = 25 000 £. La serre n’est pas finie parce que le verre n’est toujours pas arrivé (<i lang="en">the builders have been waiting for the glass since March</i>).</p><p lang="en">We haven’t found a solution for the water yet. They’ve been waiting for the glass since March. More than two hundred people have taken part in the workshops so far.</p><p><i lang="en">Present perfect simple</i> pour le bilan et les nombres (<i lang="en">we’ve raised, have taken part</i>), continu pour une activité qui dure (<i lang="en">have been waiting, have been organising</i>), <i lang="en">yet</i> en fin de phrase négative.</p>'},
]},
);
})();
